* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f4f6f9;
  color: #333;
}

h1 {
  text-align: center;
  padding: 18px 0 6px;
  font-size: 1.5rem;
  color: #2c3e50;
}

.container {
  display: flex;
  gap: 24px;
  padding: 12px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* ---------- Bubble chart panel ---------- */
.chart-panel {
  flex: 1 1 55%;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 16px;
  min-width: 0;
}

.chart-panel h2 {
  font-size: 1rem;
  margin-bottom: 8px;
  color: #34495e;
}

#bubble-chart {
  width: 100%;
  position: relative;
}

#bubble-chart svg {
  display: block;
  width: 100%;
  height: auto;
}

/* ---------- Legend ---------- */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  margin-top: 10px;
  padding: 6px 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.78rem;
  color: #555;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* ---------- Data table panel ---------- */
.table-panel {
  flex: 1 1 42%;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.1);
  padding: 16px;
  min-width: 0;
  max-height: 700px;
  overflow-y: auto;
}

.table-panel h2 {
  font-size: 1rem;
  margin-bottom: 8px;
  color: #34495e;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #34495e;
  color: #fff;
  padding: 8px 10px;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}

#stock-table tbody td {
  padding: 6px 10px;
  border-bottom: 1px solid #e8e8e8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 220px;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background .15s;
}

#stock-table tbody tr:hover {
  background: #eaf2fb;
}

#stock-table tbody tr.selected {
  background: #d0e4f7;
  font-weight: 600;
}

/* ---------- Tooltip ---------- */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(44, 62, 80, .92);
  color: #fff;
  padding: 8px 12px;
  border-radius: 5px;
  font-size: 0.78rem;
  line-height: 1.45;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .15s;
  z-index: 100;
}

/* ---------- Bubble styles ---------- */
.bubble {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1.5;
  transition: stroke-width .15s, stroke .15s;
}

.bubble.selected {
  stroke: #2c3e50;
  stroke-width: 3;
}

.bubble-label {
  pointer-events: none;
  text-anchor: middle;
  dominant-baseline: central;
  fill: #fff;
  font-weight: 700;
  font-size: 10px;
}

