/* ===================================================================
   Stock Bubble Chart + Data Table  –  D3.js v6
   =================================================================== */

(function () {
  "use strict";

  /* ---------- colour palette by sector ---------- */
  const sectorColors = {
    "Information Technology": "#4e79a7",
    "Industry":              "#f28e2b",
    "Energy":                "#e15759",
    "Financial":             "#76b7b2",
    "ETF":                   "#999999"
  };

  const colorOf = d => sectorColors[d.sector] || "#aaa";

  /* ---------- helpers ---------- */
  function fmtCap(v) {
    if (v == null || isNaN(v) || v === "") return "—";
    v = +v;
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(2)  + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(2)  + "M";
    return v.toLocaleString();
  }

  /* ---------- load CSV ---------- */
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(function (d) {
      return {
        ticker:    d.ticker,
        name:      d["full name"],
        sector:    d.sector,
        marketCap: d.marketCap ? +d.marketCap : null,
        country:   d.country || null,
        website:   d.website || null,
        isETF:     d.sector === "ETF"
      };
    });

    buildBubbleChart(data);
    buildTable(data);
  });

  /* =================================================================
     Bubble chart
     ================================================================= */
  function buildBubbleChart(data) {
    const width  = 700;
    const height = 620;

    /* --- radius scale (market cap) --- */
    const caps = data.filter(d => d.marketCap).map(d => d.marketCap);
    const rScale = d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([12, 52]);

    const ETF_RADIUS = 14;

    function radius(d) {
      return d.isETF ? ETF_RADIUS : rScale(d.marketCap);
    }

    /* --- sector cluster positions --- */
    const sectors = [...new Set(data.map(d => d.sector))];
    // Place sector centres in a grid-like arrangement around the centre
    const sectorCenters = {};
    const cols = 3;
    const xGap = width / (cols + 1);
    const rows = Math.ceil(sectors.length / cols);
    const yGap = height / (rows + 1);
    sectors.forEach(function (s, i) {
      const col = i % cols;
      const row = Math.floor(i / cols);
      sectorCenters[s] = {
        x: xGap * (col + 1),
        y: yGap * (row + 1)
      };
    });

    /* --- tooltip --- */
    const tooltip = d3.select("#bubble-chart")
      .append("div")
      .attr("class", "tooltip");

    /* --- SVG --- */
    const svg = d3.select("#bubble-chart")
      .append("svg")
      .attr("viewBox", [0, 0, width, height])
      .attr("preserveAspectRatio", "xMidYMid meet");

    /* --- nodes (copy positions) --- */
    const nodes = data.map(function (d) {
      return Object.assign({}, d, {
        r: radius(d),
        x: sectorCenters[d.sector].x + (Math.random() - 0.5) * 40,
        y: sectorCenters[d.sector].y + (Math.random() - 0.5) * 40
      });
    });

    /* --- force simulation --- */
    const simulation = d3.forceSimulation(nodes)
      .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.35))
      .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.35))
      .force("collide", d3.forceCollide(d => d.r + 2).strength(1).iterations(4))
      .force("center", d3.forceCenter(width / 2, height / 2).strength(0.05))
      .alphaDecay(0.02)
      .on("tick", ticked);

    /* --- draw bubbles --- */
    const bubbleG = svg.selectAll(".bubble-g")
      .data(nodes)
      .join("g")
      .attr("class", "bubble-g");

    bubbleG.append("circle")
      .attr("class", "bubble")
      .attr("r", d => d.r)
      .attr("fill", d => colorOf(d))
      .on("mouseover", function (event, d) {
        if (d.isETF) return;
        tooltip
          .style("opacity", 1)
          .html(
            "<strong>" + d.ticker + "</strong><br>" +
            d.name + "<br>" +
            "Sector: " + d.sector
          );
      })
      .on("mousemove", function (event) {
        const chartRect = document.getElementById("bubble-chart").getBoundingClientRect();
        tooltip
          .style("left", (event.clientX - chartRect.left + 14) + "px")
          .style("top",  (event.clientY - chartRect.top  - 10) + "px");
      })
      .on("mouseout", function () {
        tooltip.style("opacity", 0);
      })
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    /* --- labels inside bubbles --- */
    bubbleG.append("text")
      .attr("class", "bubble-label")
      .style("font-size", d => Math.max(8, Math.min(d.r * 0.55, 14)) + "px")
      .text(d => d.ticker);

    function ticked() {
      bubbleG.attr("transform", d => "translate(" + d.x + "," + d.y + ")");
    }

    /* --- legend --- */
    const legendDiv = d3.select("#bubble-chart")
      .append("div")
      .attr("class", "legend");

    sectors.forEach(function (s) {
      const item = legendDiv.append("div").attr("class", "legend-item");
      item.append("div")
        .attr("class", "legend-swatch")
        .style("background", sectorColors[s]);
      item.append("span").text(s);
    });

    /* --- expose selection for table linkage --- */
    window._bubbleNodes  = nodes;
    window._bubbleGroups = bubbleG;
  }

  /* =================================================================
     Data table
     ================================================================= */
  function buildTable(data) {
    const table = d3.select("#stock-table");

    /* header */
    const thead = table.append("thead").append("tr");
    ["Ticker Symbol", "Full Company Name", "Sector", "Market Cap"].forEach(function (h) {
      thead.append("th").text(h);
    });

    /* body */
    const tbody = table.append("tbody");
    const rows = tbody.selectAll("tr")
      .data(data)
      .join("tr")
      .attr("data-ticker", d => d.ticker)
      .on("click", function (event, d) {
        selectStock(d.ticker);
      });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d.name);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => fmtCap(d.marketCap));

    window._tableRows = rows;
  }

  /* =================================================================
     Cross-selection logic
     ================================================================= */
  let currentTicker = null;

  function selectStock(ticker) {
    /* Toggle off if already selected */
    if (currentTicker === ticker) {
      currentTicker = null;
      clearSelection();
      return;
    }
    currentTicker = ticker;

    /* Highlight bubble */
    if (window._bubbleGroups) {
      window._bubbleGroups.select("circle")
        .classed("selected", d => d.ticker === ticker);
    }

    /* Highlight table row & scroll into view */
    if (window._tableRows) {
      window._tableRows.classed("selected", d => d.ticker === ticker);
      const row = document.querySelector('#stock-table tr[data-ticker="' + ticker + '"]');
      if (row) {
        row.scrollIntoView({ behavior: "smooth", block: "center" });
      }
    }
  }

  function clearSelection() {
    if (window._bubbleGroups) {
      window._bubbleGroups.select("circle").classed("selected", false);
    }
    if (window._tableRows) {
      window._tableRows.classed("selected", false);
    }
  }
})();

